import fs from 'node:fs/promises';
import path from 'node:path';

const SEGMENT = /^[a-z0-9_-]+(?:\.[a-z0-9_-]+)*$/;
const DEVICE_STEM = /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/;
const OPERATIONS = new Set(['write', 'delete']);

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function isPlainObject(value) {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function hasExactKeys(value, keys) {
  const own = Reflect.ownKeys(value);
  return own.length === keys.length && keys.every(key => Object.hasOwn(value, key));
}

/** Returns the path's segments, or null if the path is not a portable relative path. */
function splitPortable(relative) {
  if (typeof relative !== 'string' || relative === '') return null;
  const segments = relative.split('/');
  for (const segment of segments) {
    if (!SEGMENT.test(segment)) return null;
    if (DEVICE_STEM.test(segment.split('.')[0])) return null;
  }
  return segments;
}

function parseManifest(manifest) {
  if (!isPlainObject(manifest) || !hasExactKeys(manifest, ['writes', 'deletes'])) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest must contain exactly writes and deletes');
  }
  const { writes, deletes } = manifest;
  if (!Array.isArray(writes) || !Array.isArray(deletes)) {
    throw fail('ERR_INVALID_MANIFEST', 'Manifest writes and deletes must be arrays');
  }

  // Snapshot every value once so later reads of the untrusted object cannot change it.
  const targets = [];
  for (let i = 0; i < writes.length; i++) {
    const item = writes[i];
    if (!isPlainObject(item) || !hasExactKeys(item, ['path', 'content'])) {
      throw fail('ERR_INVALID_MANIFEST', 'Each write must be exactly {path, content}');
    }
    const { path: relative, content } = item;
    if (typeof relative !== 'string' || typeof content !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Write path and content must be strings');
    }
    targets.push({ operation: 'write', relative, content });
  }
  for (let i = 0; i < deletes.length; i++) {
    const relative = deletes[i];
    if (typeof relative !== 'string') {
      throw fail('ERR_INVALID_MANIFEST', 'Each delete must be a path string');
    }
    targets.push({ operation: 'delete', relative });
  }

  for (const target of targets) {
    target.segments = splitPortable(target.relative);
    if (target.segments === null) {
      throw fail('ERR_INVALID_PATH', `Invalid path: ${JSON.stringify(target.relative)}`);
    }
  }

  const seen = new Set();
  for (const { relative } of targets) {
    if (seen.has(relative)) throw fail('ERR_INVALID_MANIFEST', `Duplicate target: ${relative}`);
    seen.add(relative);
  }
  for (const { segments, relative } of targets) {
    for (let depth = 1; depth < segments.length; depth++) {
      const ancestor = segments.slice(0, depth).join('/');
      if (seen.has(ancestor)) {
        throw fail('ERR_INVALID_MANIFEST', `Target ${ancestor} is an ancestor of ${relative}`);
      }
    }
  }
  return targets;
}

function parseGrants(grants) {
  if (!Array.isArray(grants)) throw fail('ERR_INVALID_GRANT', 'Grants must be an array');
  const approved = new Set();
  for (let i = 0; i < grants.length; i++) {
    const grant = grants[i];
    if (!isPlainObject(grant) || !hasExactKeys(grant, ['path', 'operation'])) {
      throw fail('ERR_INVALID_GRANT', 'Each grant must be exactly {path, operation}');
    }
    const { path: relative, operation } = grant;
    if (!OPERATIONS.has(operation) || splitPortable(relative) === null) {
      throw fail('ERR_INVALID_GRANT', 'Grant has an invalid path or operation');
    }
    approved.add(`${operation}\0${relative}`);
  }
  return approved;
}

async function lstatOrNull(location) {
  try {
    return await fs.lstat(location);
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

async function assertSafeTarget(directory, { segments, relative }) {
  let location = directory;
  for (let i = 0; i < segments.length; i++) {
    location = path.join(location, segments[i]);
    const stats = await lstatOrNull(location);
    if (stats === null) return; // Remaining components are absent.
    const last = i === segments.length - 1;
    if (stats.isSymbolicLink() || (last ? !stats.isFile() : !stats.isDirectory())) {
      throw fail('ERR_UNSAFE_TARGET', `Unsafe target: ${relative}`);
    }
  }
}

export async function restore(directory, manifest, grants) {
  const targets = parseManifest(manifest);
  const approved = parseGrants(grants);

  for (const { operation, relative } of targets) {
    if (!approved.has(`${operation}\0${relative}`)) {
      throw fail('ERR_DENIED', `${operation} not approved: ${relative}`);
    }
  }

  const root = await fs.lstat(directory);
  if (root.isSymbolicLink() || !root.isDirectory()) {
    throw fail('ERR_UNSAFE_TARGET', 'Restore root must be a real directory');
  }
  for (const target of targets) await assertSafeTarget(directory, target);

  const written = [];
  const deleted = [];
  for (const target of targets) {
    const location = path.join(directory, ...target.segments);
    if (target.operation === 'write') {
      await fs.mkdir(path.dirname(location), { recursive: true });
      await fs.writeFile(location, target.content, 'utf8');
      written.push(target.relative);
    } else {
      try {
        await fs.unlink(location);
        deleted.push(target.relative);
      } catch (error) {
        if (error.code !== 'ENOENT') throw error;
      }
    }
  }
  return { written, deleted };
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const { restore } = await import(pathToFileURL(path.resolve(process.argv[2], 'src/restore.js')));

const results = [];
async function ws() {
  const d = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-smoke-'));
  await fs.writeFile(path.join(d, '.hidden'), 'h');
  await fs.mkdir(path.join(d, 'sub'));
  await fs.writeFile(path.join(d, 'sub/keep.txt'), 'k');
  await fs.writeFile(path.join(d, 'old.txt'), 'o');
  return d;
}
async function expectCode(name, fn, code) {
  const d = await ws();
  try { await fn(d); results.push(`${name}: FAIL resolved`); }
  catch (e) {
    const intact = await fs.readFile(path.join(d, '.hidden'), 'utf8') === 'h'
      && await fs.readFile(path.join(d, 'old.txt'), 'utf8') === 'o'
      && (await fs.readdir(d)).sort().join() === ['.hidden', 'old.txt', 'sub', ...(e.extra ?? [])].sort().join();
    results.push(`${name}: ${e.code === code ? 'ok' : 'FAIL ' + e.code + ' ' + e.message}${intact ? '' : ' (root changed: ' + (await fs.readdir(d)) + ')'}`);
  }
  await fs.rm(d, { recursive: true, force: true });
}
const W = (p, c = 'x') => ({ path: p, content: c });
const g = (p, operation = 'write') => ({ path: p, operation });

await expectCode('approved flag', d => restore(d, { writes: [W('a.txt')], deletes: [], approved: true }, []), 'ERR_INVALID_MANIFEST');
await expectCode('cleanupCommand', d => restore(d, { writes: [], deletes: [], cleanupCommand: 'rm -rf' }, []), 'ERR_INVALID_MANIFEST');
await expectCode('write extra key', d => restore(d, { writes: [{ ...W('a.txt'), replace: true }], deletes: [] }, [g('a.txt')]), 'ERR_INVALID_MANIFEST');
await expectCode('non-string content', d => restore(d, { writes: [{ path: 'a.txt', content: 1 }], deletes: [] }, [g('a.txt')]), 'ERR_INVALID_MANIFEST');
await expectCode('null manifest', d => restore(d, null, []), 'ERR_INVALID_MANIFEST');
await expectCode('dup write/delete', d => restore(d, { writes: [W('a.txt')], deletes: ['a.txt'] }, [g('a.txt'), g('a.txt', 'delete')]), 'ERR_INVALID_MANIFEST');
await expectCode('ancestor', d => restore(d, { writes: [W('a/b.txt')], deletes: ['a'] }, [g('a/b.txt'), g('a', 'delete')]), 'ERR_INVALID_MANIFEST');
for (const p of ['../x', '/abs', 'a//b', 'a\\b', 'c:x', 'A.txt', 'con', 'nul.txt', 'com1.tar.gz', './a', 'a/', '']) {
  await expectCode(`path ${JSON.stringify(p)}`, d => restore(d, { writes: [W(p)], deletes: [] }, []), 'ERR_INVALID_PATH');
}
await expectCode('prefix grant', d => restore(d, { writes: [W('sub/new.txt')], deletes: [] }, [g('sub')]), 'ERR_DENIED');
await expectCode('string-prefix grant', d => restore(d, { writes: [W('old.txt2')], deletes: [] }, [g('old.txt')]), 'ERR_DENIED');
await expectCode('wrong op', d => restore(d, { writes: [], deletes: ['old.txt'] }, [g('old.txt')]), 'ERR_DENIED');
await expectCode('partial approval no write', d => restore(d, { writes: [W('new/a.txt'), W('b.txt')], deletes: [] }, [g('new/a.txt')]), 'ERR_DENIED');
await expectCode('bad grant op', d => restore(d, { writes: [], deletes: [] }, [g('a', 'read')]), 'ERR_INVALID_GRANT');
await expectCode('bad grant path', d => restore(d, { writes: [], deletes: [] }, [g('../a')]), 'ERR_INVALID_GRANT');
await expectCode('grant extra key', d => restore(d, { writes: [], deletes: [] }, [{ ...g('a'), all: true }]), 'ERR_INVALID_GRANT');
await expectCode('dir target', d => restore(d, { writes: [W('sub')], deletes: [] }, [g('sub')]), 'ERR_UNSAFE_TARGET');
await expectCode('delete dir', d => restore(d, { writes: [], deletes: ['sub'] }, [g('sub', 'delete')]), 'ERR_UNSAFE_TARGET');
await expectCode('file as ancestor', d => restore(d, { writes: [W('old.txt/x')], deletes: [] }, [g('old.txt/x')]), 'ERR_UNSAFE_TARGET');

// Symlinks / junctions (inside root), plus earlier approved write must not happen.
for (const type of ['junction', 'file']) {
  const d = await ws();
  const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-outside-'));
  try {
    if (type === 'junction') await fs.symlink(path.join(d, 'sub'), path.join(d, 'link'), 'junction');
    else await fs.symlink(path.join(d, 'old.txt'), path.join(d, 'link'), 'file');
    const target = type === 'junction' ? 'link/keep.txt' : 'link';
    await restore(d, { writes: [W('first/a.txt'), W(target, 'evil')], deletes: [] }, [g('first/a.txt'), g(target)]);
    results.push(`symlink ${type}: FAIL resolved`);
  } catch (e) {
    const untouched = await fs.readFile(path.join(d, 'sub/keep.txt'), 'utf8') === 'k'
      && await fs.readFile(path.join(d, 'old.txt'), 'utf8') === 'o'
      && !(await fs.readdir(d)).includes('first');
    results.push(`symlink ${type}: ${e.code === 'ERR_UNSAFE_TARGET' && untouched ? 'ok' : 'FAIL ' + e.code + ' ' + e.message}`);
  }
  // Root itself as symlink
  try {
    await restore(path.join(d, 'link'), { writes: [], deletes: [] }, []);
    results.push(`root ${type}: FAIL resolved`);
  } catch (e) { results.push(`root ${type}: ${e.code === 'ERR_UNSAFE_TARGET' ? 'ok' : 'FAIL ' + e.code + ' ' + e.message}`); }
  await fs.rm(d, { recursive: true, force: true });
  await fs.rm(outside, { recursive: true, force: true });
}

// Success path
{
  const d = await ws();
  const r = await restore(d, { writes: [W('old.txt', 'new'), W('deep/x/y.txt', 'y')], deletes: ['sub/keep.txt', 'gone.txt'] },
    [g('old.txt'), g('old.txt'), g('deep/x/y.txt'), g('sub/keep.txt', 'delete'), g('gone.txt', 'delete')]);
  const ok = JSON.stringify(r) === JSON.stringify({ written: ['old.txt', 'deep/x/y.txt'], deleted: ['sub/keep.txt'] })
    && await fs.readFile(path.join(d, 'old.txt'), 'utf8') === 'new'
    && await fs.readFile(path.join(d, '.hidden'), 'utf8') === 'h'
    && (await fs.stat(path.join(d, 'sub'))).isDirectory();
  results.push(`success: ${ok ? 'ok' : 'FAIL ' + JSON.stringify(r)}`);
  const empty = await restore(d, { writes: [], deletes: [] }, []);
  results.push(`empty: ${JSON.stringify(empty) === '{"written":[],"deleted":[]}' ? 'ok' : 'FAIL'}`);
  await fs.rm(d, { recursive: true, force: true });
}
console.log(results.join('\n'));
